package com.example.starter.epidemic.domain;

/**
 * 报告卡生命周期状态。
 */
public enum CardStatus {

    /** 初报/订正后待审核。 */
    PENDING_REVIEW,
    /** 审核通过，可订正、可终审归档。 */
    APPROVED,
    /** 审核通过前撤回，终态不可恢复。 */
    WITHDRAWN,
    /** 终审归档，终态只读；仅双人特殊订正可追加版本。 */
    ARCHIVED
}

package com.example.starter.epidemic.domain;

/**
 * 诊断类型：疑似/确诊。疑似转确诊属于病种变更类订正，须重起审核。
 */
public enum DiagnosisType {
    SUSPECTED,
    CONFIRMED
}

package com.example.starter.epidemic.domain;

/**
 * 时限判定结果。提交时刻恰在时限终点视为及时。
 */
public enum Timeliness {
    TIMELY,
    LATE
}

package com.example.starter.epidemic.domain;

/**
 * 版本来源。
 */
public enum ChangeKind {
    /** 初报版本。 */
    INITIAL,
    /** 审核通过后、归档前的普通订正。 */
    CORRECTION,
    /** 归档后经两名不同审核员确认生效的特殊订正。 */
    SPECIAL
}

package com.example.starter.epidemic.domain;

/**
 * 审核记录结论。病种变更重起审核时，旧结论标记为 VOIDED 作废留痕。
 */
public enum ReviewOutcome {
    APPROVED,
    VOIDED
}

package com.example.starter.epidemic.domain;

/**
 * 审核阶段。
 */
public enum ReviewStage {
    /** 初审（初报/订正后的常规审核）。 */
    REVIEW,
    /** 终审归档。 */
    FINAL,
    /** 特殊订正双人确认。 */
    SPECIAL
}

package com.example.starter.epidemic.domain;

/**
 * 特殊订正状态。
 */
public enum SpecialStatus {
    /** 确认人数不足两名，尚未生效。 */
    PENDING,
    /** 两名不同审核员确认完成，已生成新版本生效。 */
    APPLIED
}

package com.example.starter.epidemic.domain;

/**
 * 幂等请求类型。
 */
public enum RequestType {
    INITIAL,
    CORRECTION,
    SPECIAL
}

