package com.example.starter.epidemic.api;

/**
 * 初报/订正提交结果。
 *
 * @param duplicated        是否命中“同一患者+病种+发病日期”重复去重（未新建卡）
 * @param replayed          是否命中同 requestId 幂等重放（返回首次结果）
 * @param existingCardNumber 去重命中时已存在的卡片编号
 */
public record SubmitResult(
        String cardNumber,
        int versionNo,
        String status,
        boolean timely,
        boolean duplicated,
        boolean replayed,
        String existingCardNumber
) {
}

package com.example.starter.epidemic.api;

/**
 * 审核/撤回/归档等状态动作的返回结果。
 *
 * @param idempotentHit 是否为幂等重放（如对已归档卡重复归档返回成功）
 */
public record ActionResult(
        String cardNumber,
        String status,
        int currentVersion,
        boolean idempotentHit,
        String message
) {
}

package com.example.starter.epidemic.api;

import java.time.OffsetDateTime;

/**
 * 审核轨迹条目。病种变更重起审核时旧条目标记 voided=true 作废留痕。
 */
public record ReviewView(
        int versionNo,
        String stage,
        String reviewer,
        String outcome,
        boolean voided,
        String opinion,
        OffsetDateTime createdAt
) {
}

package com.example.starter.epidemic.api;

import java.time.OffsetDateTime;
import java.util.List;

/**
 * 报告卡查询视图，含完整版本链与审核轨迹，结果可稳定复算。
 */
public record CardView(
        String cardNumber,
        String patientId,
        String patientName,
        String diseaseCode,
        String onsetDate,
        String status,
        int currentVersion,
        OffsetDateTime createdAt,
        OffsetDateTime updatedAt,
        VersionView current,
        List<VersionView> versions,
        List<ReviewView> reviews
) {
}

package com.example.starter.epidemic.api;

/**
 * 特殊订正发起/确认结果。
 *
 * @param effective 是否已生效（两名不同审核员确认完成）
 * @param appliedVersionNo 生效时生成的新版本号
 */
public record SpecialCorrectionView(
        String requestId,
        String cardNumber,
        String status,
        String confirmer1,
        String confirmer2,
        boolean effective,
        Integer appliedVersionNo,
        String message
) {
}

