        args[i++] = now;
        args[i++] = cardNumber;
        for (String s : expectedStatuses) {
            args[i++] = s;
        }
        return jdbc.update(sql, args);
    }

    /**
     * 撤回：仅待审核卡可撤回；同时释放去重位（dedup_slot 置 NULL），撤回为终态。
     */
    public int withdraw(String cardNumber, LocalDateTime now) {
        return jdbc.update(
                "UPDATE epidemic_card SET status = 'WITHDRAWN', dedup_slot = NULL, updated_at = ? "
                        + "WHERE card_number = ? AND status = 'PENDING_REVIEW'",
                now, cardNumber);
    }

    /**
     * 归档卡经特殊订正追加版本：状态保持 ARCHIVED，仅推进版本与最新病种信息。
     */
